(() => {
'use strict';
let DATA=null, MANIFEST=null, selectedGw=1, rankMode='overall', chapterFilter='ALL';
const rankCache=new Map(), groupCache=new Map();
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const enc=v=>encodeURIComponent(v);
const dec=v=>{try{return decodeURIComponent(v)}catch{return v}};
const nfmt=n=>Number(n||0).toLocaleString('en-MY');
const avg=a=>a.length?Math.round((a.reduce((s,x)=>s+x,0)/a.length)*10)/10:0;
const median=a=>{if(!a.length)return 0;const x=[...a].sort((a,b)=>a-b),m=Math.floor(x.length/2);return x.length%2?x[m]:(x[m-1]+x[m])/2};
function initials(name){return String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),1800)}
function movement(v){if(v==null)return '<span class="movement flat">—</span>';if(v>0)return `<span class="movement up">↑${v}</span>`;if(v<0)return `<span class="movement down">↓${Math.abs(v)}</span>`;return '<span class="movement flat">—</span>'}
function rankClass(r){return r<=3?'rank-num top':'rank-num'}
function statusLabel(){if(selectedGw!==DATA.meta.gw)return {text:`GW${selectedGw} ARCHIVE`,cls:'archive'};const s=String(DATA.meta.status||'').toUpperCase();return {text:s==='SNAPSHOT'?'SNAPSHOT':s,cls:s.toLowerCase()}}
function updateChrome(){
  $('#seasonLabel').textContent=DATA.meta.season;
  $('#updatedLabel').textContent=`Updated ${formatDate(DATA.meta.updated_at)}`;
  const s=statusLabel(),p=$('#statusPill');p.className=`status-pill ${s.cls}`;p.innerHTML=`<i></i><span>${esc(s.text)}</span>`;
  $$('[data-nav]').forEach(a=>a.classList.remove('active'));
  const route=getRoute()[0]; const key=['manager'].includes(route)?'individual':['group'].includes(route)?'groups':['chapter'].includes(route)?'chapters':['statistics','hall'].includes(route)?'more':route;
  $(`[data-nav="${key}"]`)?.classList.add('active');
}
function formatDate(iso){try{return new Intl.DateTimeFormat('en-MY',{timeZone:'Asia/Kuala_Lumpur',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(iso))}catch{return iso}}
function competitionRank(rows,key='total'){
  rows.sort((a,b)=>(Number(b[key]||0)-Number(a[key]||0))||String(a.team_name||a.chapter||'').localeCompare(String(b.team_name||b.chapter||'')));
  let prev=null,rank=0;rows.forEach((r,i)=>{if(prev===null||r[key]!==prev){rank=i+1;prev=r[key]}r.rank=rank});return rows;
}
function historiesFor(id,gw=selectedGw){return (DATA.histories[id]||[]).slice(0,gw).map(Number)}
function historicalRanking(gw=selectedGw){
  if(rankCache.has(gw))return rankCache.get(gw);
  let rows=DATA.individual.map(base=>{const hs=historiesFor(base.id,gw);return {...base,gw_score:Number(hs[gw-1]||0),total:hs.reduce((s,x)=>s+x,0),move:null,chapter_rank:null}});
  competitionRank(rows,'total');
  if(gw>1){const prev=historicalRanking(gw-1),map=new Map(prev.map(x=>[x.id,x.rank]));rows.forEach(r=>r.move=(map.get(r.id)??r.rank)-r.rank)}
  const chapters={};rows.forEach(r=>(chapters[r.chapter]??=[]).push(r));Object.values(chapters).forEach(list=>{const cp=list.map(x=>({...x}));competitionRank(cp,'total');const m=new Map(cp.map(x=>[x.id,x.rank]));list.forEach(x=>x.chapter_rank=m.get(x.id))});
  rankCache.set(gw,rows);return rows;
}
function groupRankings(gw=selectedGw){
  if(groupCache.has(gw))return groupCache.get(gw);
  const rows=historicalRanking(gw),eligible=new Set(DATA.chapters.filter(c=>c.group_eligible).map(c=>c.chapter)),by={};rows.forEach(r=>(by[r.chapter]??=[]).push(r));
  const groups=[];
  for(const chapter of eligible){
    const members=by[chapter]||[];const top5=[...members].sort((a,b)=>b.gw_score-a.gw_score||a.team_name.localeCompare(b.team_name)).slice(0,5);
    let total=0;for(let e=1;e<=gw;e++){const vals=members.map(m=>Number((DATA.histories[m.id]||[])[e-1]||0)).sort((a,b)=>b-a).slice(0,5);total+=vals.reduce((s,x)=>s+x,0)}
    groups.push({chapter,managers:members.length,gw_score:top5.reduce((s,x)=>s+x.gw_score,0),total,top5,cut_line:top5.length?top5[top5.length-1].gw_score:0,move:null});
  }
  competitionRank(groups,'total');
  if(gw>1){const prev=groupRankings(gw-1),m=new Map(prev.map(x=>[x.chapter,x.rank]));groups.forEach(g=>g.move=(m.get(g.chapter)??g.rank)-g.rank)}
  groupCache.set(gw,groups);return groups;
}
function chapterStats(gw=selectedGw){
  const rows=historicalRanking(gw),by={};rows.forEach(r=>(by[r.chapter]??=[]).push(r));const gr=new Map(groupRankings(gw).map(g=>[g.chapter,g.rank]));
  return DATA.chapters.map(c=>{const list=by[c.chapter]||[],best=[...list].sort((a,b)=>a.rank-b.rank)[0];return {...c,gw_average:avg(list.map(x=>x.gw_score)),overall_average:avg(list.map(x=>x.total)),group_rank:gr.get(c.chapter)||null,best_manager:best?{id:best.id,team_name:best.team_name,manager_name:best.manager_name,rank:best.rank}:null}}).sort((a,b)=>a.participation_rank-b.participation_rank||a.chapter.localeCompare(b.chapter));
}
function pageHeader(title,sub=''){return `<div class="page-head"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div></div>`}
function hero(){return `<section class="hero"><div class="eyebrow">${selectedGw===DATA.meta.gw?esc(DATA.meta.status):'ARCHIVE'} • GAMEWEEK ${selectedGw}</div><h1>ANSARA FPL</h1><p>Live competition rankings, chapter battles and season records in one place.</p><div class="hero-meta"><span>${nfmt(DATA.meta.managers)} Managers</span><span>${nfmt(DATA.meta.chapters)} Chapters</span><span>${nfmt(DATA.meta.group_chapters)} Group Eligible</span></div></section>`}
function miniTable(rows,limit=10){return `<div class="table-wrap"><table class="rank-table"><thead><tr><th>#</th><th>Team / Manager</th><th>Chapter</th><th>Move</th><th style="text-align:right">GW</th><th style="text-align:right">Total</th></tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr><td class="${rankClass(r.rank)}">${r.rank}</td><td><a class="team-link" href="#/manager/${r.id}">${esc(r.team_name)}</a><span class="subline">${esc(r.manager_name)}</span></td><td><a class="chapter-link" href="#/chapter/${enc(r.chapter)}">${esc(r.chapter)}</a></td><td>${movement(r.move)}</td><td class="score">${nfmt(r.gw_score)}</td><td class="score">${nfmt(r.total)}</td></tr>`).join('')}</tbody></table></div>`}
function homePage(){
  const rows=historicalRanking(),groups=groupRankings(),leader=rows[0],gleader=groups[0],gwScores=rows.map(r=>r.gw_score),movers=rows.filter(r=>r.move!=null).sort((a,b)=>b.move-a.move).slice(0,5);
  return `${hero()}<div class="kpis"><div class="kpi"><span>Overall Leader</span><strong>#${leader?.rank||'—'}</strong><small>${esc(leader?.team_name||'—')}</small></div><div class="kpi"><span>GW Leader</span><strong>${nfmt(Math.max(...gwScores,0))}</strong><small>${esc([...rows].sort((a,b)=>b.gw_score-a.gw_score)[0]?.team_name||'—')}</small></div><div class="kpi"><span>Leading Group</span><strong>#${gleader?.rank||'—'}</strong><small>${esc(gleader?.chapter||'—')}</small></div><div class="kpi"><span>Average GW</span><strong>${avg(gwScores)}</strong><small>Median ${median(gwScores)}</small></div></div>
  <section class="section"><div class="section-head"><h2>Overall Top 10</h2><a href="#/individual">View all</a></div>${miniTable(rows,10)}</section>
  <section class="section"><div class="section-head"><h2>Group Top 5</h2><a href="#/groups">View all</a></div><div class="table-wrap"><table class="rank-table compact"><thead><tr><th>#</th><th>Chapter</th><th>Move</th><th style="text-align:right">GW</th><th style="text-align:right">Total</th></tr></thead><tbody>${groups.slice(0,5).map(g=>`<tr><td class="${rankClass(g.rank)}">${g.rank}</td><td><a class="chapter-link" href="#/group/${enc(g.chapter)}">${esc(g.chapter)}</a></td><td>${movement(g.move)}</td><td class="score">${nfmt(g.gw_score)}</td><td class="score">${nfmt(g.total)}</td></tr>`).join('')}</tbody></table></div></section>
  ${selectedGw>1?`<section class="section"><div class="section-head"><h2>Biggest Climbers</h2></div>${movers.length?movers.map(r=>`<div class="hof-item"><div class="gw">↑${r.move}</div><div><strong><a class="team-link" href="#/manager/${r.id}">${esc(r.team_name)}</a></strong><small>${esc(r.manager_name)} • ${esc(r.chapter)}</small></div><strong>#${r.rank}</strong></div>`).join(''):'<div class="empty">No rank movement yet.</div>'}</section>`:''}`;
}
function individualPage(){
  let rows=historicalRanking();if(chapterFilter!=='ALL')rows=rows.filter(r=>r.chapter===chapterFilter);if(rankMode==='gw'){rows=[...rows].sort((a,b)=>b.gw_score-a.gw_score||a.rank-b.rank);let prev=null,rank=0;rows.forEach((r,i)=>{if(prev===null||r.gw_score!==prev){rank=i+1;prev=r.gw_score}r.displayRank=rank})}else rows=rows.map(r=>({...r,displayRank:r.rank}));
  const chapters=[...new Set(DATA.individual.map(x=>x.chapter))].sort();
  return `${pageHeader('Individual Ranking',`${rows.length} managers • GW${selectedGw}`)}<div class="filters"><div class="segmented"><button data-mode="overall" class="${rankMode==='overall'?'active':''}">Overall</button><button data-mode="gw" class="${rankMode==='gw'?'active':''}">Gameweek</button></div><select id="chapterFilter" class="filter-select"><option value="ALL">All Chapters</option>${chapters.map(c=>`<option ${chapterFilter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><section class="section">${`<div class="table-wrap"><table class="rank-table"><thead><tr><th>#</th><th>Team / Manager</th><th>Chapter</th><th>Chapter #</th><th>Move</th><th style="text-align:right">GW</th><th style="text-align:right">Total</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="${rankClass(r.displayRank)}">${r.displayRank}</td><td><a class="team-link" href="#/manager/${r.id}">${esc(r.team_name)}</a><span class="subline">${esc(r.manager_name)}</span></td><td><a class="chapter-link" href="#/chapter/${enc(r.chapter)}">${esc(r.chapter)}</a></td><td>#${r.chapter_rank}</td><td>${movement(r.move)}</td><td class="score">${nfmt(r.gw_score)}</td><td class="score">${nfmt(r.total)}</td></tr>`).join('')}</tbody></table></div>`}</section>`;
}
function groupsPage(){const groups=groupRankings();return `${pageHeader('Group Ranking',`${groups.length} eligible chapters • Top 5 scores counted`)}<div class="card-grid">${groups.map(g=>groupCard(g)).join('')}</div>`}
function groupCard(g){return `<article class="group-card"><div class="group-card-head"><div><h3><a class="chapter-link" href="#/group/${enc(g.chapter)}">${esc(g.chapter)}</a></h3><span class="subline">${g.managers} managers • cut line ${g.cut_line}</span></div><div class="big-rank">#${g.rank}</div></div><div class="stat-row"><div><span>GW${selectedGw}</span><strong>${nfmt(g.gw_score)}</strong></div><div><span>Cumulative</span><strong>${nfmt(g.total)}</strong></div><div><span>Movement</span><strong>${g.move==null?'—':g.move>0?'↑'+g.move:g.move<0?'↓'+Math.abs(g.move):'—'}</strong></div></div><div class="top5-list">${g.top5.map((x,i)=>`<div class="top5-item"><a href="#/manager/${x.id}">${i+1}. ${esc(x.team_name)}<span class="subline">${esc(x.manager_name)}</span></a><strong>${x.gw_score}</strong></div>`).join('')}</div></article>`}
function chaptersPage(){const chapters=chapterStats();return `${pageHeader('All Chapters',`${chapters.length} chapters • participation & performance`)}<div class="card-grid">${chapters.map(c=>`<article class="chapter-card"><div class="chapter-card-head"><div><h3><a class="chapter-link" href="#/chapter/${enc(c.chapter)}">${esc(c.chapter)}</a></h3><span class="subline">Participation #${c.participation_rank}</span></div><span class="tag ${c.group_eligible?'yes':'no'}">${c.group_eligible?'Group Eligible':'Not Eligible'}</span></div><div class="stat-row"><div><span>Managers</span><strong>${c.managers}</strong></div><div><span>Group Rank</span><strong>${c.group_rank?'#'+c.group_rank:'—'}</strong></div><div><span>GW Avg</span><strong>${c.gw_average}</strong></div></div>${c.best_manager?`<div class="top5-list"><div class="top5-item"><span>Chapter leader</span><a href="#/manager/${c.best_manager.id}">#${c.best_manager.rank} ${esc(c.best_manager.team_name)}</a></div></div>`:''}</article>`).join('')}</div>`}
function managerPage(id){
  const base=DATA.individual.find(x=>x.id===id);if(!base)return notFound();const rows=historicalRanking(),r=rows.find(x=>x.id===id),hs=historiesFor(id),details=DATA.manager_details[id]||[];const ranks=[];for(let g=1;g<=selectedGw;g++){const x=historicalRanking(g).find(m=>m.id===id);ranks.push(x?.rank||0)}
  const chips=details.slice(0,selectedGw).filter(x=>x.chip).map(x=>`GW${x.gw}: ${x.chip}`).join(' • ')||'No chip data yet';
  return `${pageHeader('Manager Profile',`GW${selectedGw} view`)}<section class="profile-hero"><div class="profile-top"><div class="avatar">${esc(initials(r.manager_name))}</div><div class="profile-title"><h1>${esc(r.team_name)}</h1><p>${esc(r.manager_name)} • <a class="chapter-link" href="#/chapter/${enc(r.chapter)}">${esc(r.chapter)}</a></p></div><button class="share-btn" id="shareProfile">Share</button></div><div class="profile-kpis"><div><span>ANSARA Rank</span><strong>#${r.rank}</strong></div><div><span>Chapter Rank</span><strong>#${r.chapter_rank}</strong></div><div><span>GW${selectedGw}</span><strong>${nfmt(r.gw_score)}</strong></div><div><span>Total</span><strong>${nfmt(r.total)}</strong></div></div></section>
  <section class="section"><div class="section-head"><h2>Rank Progression</h2><span class="subline">GW1–GW${selectedGw}</span></div><div class="chart-box">${lineChart(ranks)}</div></section>
  <section class="section"><div class="section-head"><h2>Gameweek History</h2></div><div class="table-wrap"><table class="rank-table compact"><thead><tr><th>GW</th><th style="text-align:right">Score</th><th style="text-align:right">Hits</th><th>Chip</th></tr></thead><tbody>${hs.map((s,i)=>{const d=details[i]||{};return `<tr><td>GW${i+1}</td><td class="score">${s}</td><td class="score">${d.hits==null?'—':d.hits}</td><td>${esc(d.chip||'—')}</td></tr>`}).join('')}</tbody></table></div></section>
  <section class="section"><div class="section-head"><h2>Season Snapshot</h2></div><div class="stat-row" style="padding:0 14px 14px"><div><span>Average</span><strong>${avg(hs.slice(Math.max(0,r.eligible_from-1)))}</strong></div><div><span>Best GW</span><strong>${Math.max(...hs.slice(Math.max(0,r.eligible_from-1)),0)}</strong></div><div><span>Rank Move</span><strong>${r.move==null?'—':r.move>0?'↑'+r.move:r.move<0?'↓'+Math.abs(r.move):'—'}</strong></div></div><div class="notice" style="margin:0 14px 14px">${esc(chips)}</div></section>`;
}
function lineChart(values){if(!values.length)return '<div class="empty">No history.</div>';const w=600,h=150,pad=18,min=Math.min(...values),max=Math.max(...values),span=Math.max(1,max-min);const pts=values.map((v,i)=>{const x=pad+(values.length===1?0:(i/(values.length-1))*(w-pad*2)),y=pad+((v-min)/span)*(h-pad*2);return [x,y]});return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Rank progression"><line class="chart-axis" x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}"/><polyline class="chart-line" points="${pts.map(p=>p.join(',')).join(' ')}"/>${pts.map((p,i)=>`<circle class="chart-dot" cx="${p[0]}" cy="${p[1]}" r="4"/><text class="chart-label" x="${p[0]}" y="${Math.min(h-2,p[1]+15)}" text-anchor="middle">${values[i]}</text>`).join('')}</svg><div class="subline">Lower rank number is better.</div>`}
function chapterPage(name){const rows=historicalRanking().filter(r=>r.chapter===name),c=chapterStats().find(x=>x.chapter===name);if(!c)return notFound();const g=groupRankings().find(x=>x.chapter===name);return `${pageHeader(name,`${rows.length} managers • Chapter ranking`)}<div class="kpis"><div class="kpi"><span>Participation Rank</span><strong>#${c.participation_rank}</strong><small>${c.managers} managers</small></div><div class="kpi"><span>Group Rank</span><strong>${g?'#'+g.rank:'—'}</strong><small>${c.group_eligible?'Eligible':'Not eligible'}</small></div><div class="kpi"><span>GW Average</span><strong>${c.gw_average}</strong><small>GW${selectedGw}</small></div><div class="kpi"><span>Chapter Leader</span><strong>#${rows[0]?.rank||'—'}</strong><small>${esc(rows[0]?.team_name||'—')}</small></div></div>${g?`<section class="section"><div class="section-head"><h2>Top 5 Group Contributors</h2><a href="#/group/${enc(name)}">Group details</a></div>${g.top5.map((x,i)=>`<div class="hof-item"><div class="gw">${i+1}</div><div><strong><a class="team-link" href="#/manager/${x.id}">${esc(x.team_name)}</a></strong><small>${esc(x.manager_name)}</small></div><strong>${x.gw_score}</strong></div>`).join('')}</section>`:''}<section class="section"><div class="section-head"><h2>Chapter Ranking</h2></div>${miniTable(rows,rows.length)}</section>`}
function groupPage(name){const g=groupRankings().find(x=>x.chapter===name);if(!g)return notFound();const all=historicalRanking().filter(x=>x.chapter===name).sort((a,b)=>b.gw_score-a.gw_score);const topIds=new Set(g.top5.map(x=>x.id));return `${pageHeader(name,`Group details • GW${selectedGw}`)}<div class="kpis"><div class="kpi"><span>Group Rank</span><strong>#${g.rank}</strong><small>${movementText(g.move)}</small></div><div class="kpi"><span>GW Score</span><strong>${g.gw_score}</strong><small>Top 5 total</small></div><div class="kpi"><span>Cumulative</span><strong>${g.total}</strong><small>Season group points</small></div><div class="kpi"><span>Cut Line</span><strong>${g.cut_line}</strong><small>5th contributor</small></div></div><section class="section"><div class="section-head"><h2>Counted Top 5</h2></div>${g.top5.map((x,i)=>`<div class="hof-item"><div class="gw">${i+1}</div><div><strong><a class="team-link" href="#/manager/${x.id}">${esc(x.team_name)}</a></strong><small>${esc(x.manager_name)}</small></div><strong>${x.gw_score}</strong></div>`).join('')}</section><section class="section"><div class="section-head"><h2>Outside Top 5</h2></div>${all.filter(x=>!topIds.has(x.id)).length?all.filter(x=>!topIds.has(x.id)).map((x,i)=>`<div class="hof-item"><div class="gw">${i+6}</div><div><strong><a class="team-link" href="#/manager/${x.id}">${esc(x.team_name)}</a></strong><small>${esc(x.manager_name)}</small></div><strong>${x.gw_score}</strong></div>`).join(''):'<div class="empty">No additional managers.</div>'}</section>`}
function movementText(v){return v==null?'No previous GW':v>0?`Up ${v}`:v<0?`Down ${Math.abs(v)}`:'No change'}
function statisticsPage(){const rows=historicalRanking(),scores=rows.map(x=>x.gw_score),movers=rows.filter(x=>x.move!=null).sort((a,b)=>b.move-a.move),climbers=movers.filter(x=>x.move>0).slice(0,10),falls=[...movers].sort((a,b)=>a.move-b.move).filter(x=>x.move<0).slice(0,10);const consistency=rows.map(r=>{const h=historiesFor(r.id).slice(Math.max(0,r.eligible_from-1));const m=avg(h),sd=h.length>1?Math.sqrt(h.reduce((s,x)=>s+(x-m)*(x-m),0)/h.length):null;return {...r,sd}}).filter(x=>x.sd!=null).sort((a,b)=>a.sd-b.sd||b.total-a.total).slice(0,10);return `${pageHeader('Statistics',`GW${selectedGw} analytics`)}<div class="kpis"><div class="kpi"><span>Highest GW</span><strong>${Math.max(...scores,0)}</strong><small>Best score</small></div><div class="kpi"><span>Average</span><strong>${avg(scores)}</strong><small>All managers</small></div><div class="kpi"><span>Median</span><strong>${median(scores)}</strong><small>Middle score</small></div><div class="kpi"><span>Group High</span><strong>${Math.max(...groupRankings().map(g=>g.gw_score),0)}</strong><small>Top 5 total</small></div></div>${statList('Biggest Climbers',climbers,x=>`↑${x.move}`,true)}${statList('Biggest Falls',falls,x=>`↓${Math.abs(x.move)}`,true)}${statList('Most Consistent',consistency,x=>`σ ${x.sd.toFixed(1)}`,false)}`}
function statList(title,rows,value,showRank){return `<section class="section"><div class="section-head"><h2>${esc(title)}</h2></div>${rows.length?rows.map(r=>`<div class="hof-item"><div class="gw">${value(r)}</div><div><strong><a class="team-link" href="#/manager/${r.id}">${esc(r.team_name)}</a></strong><small>${esc(r.manager_name)} • ${esc(r.chapter)}</small></div>${showRank?`<strong>#${r.rank}</strong>`:''}</div>`).join(''):'<div class="empty">Available after more gameweeks.</div>'}</section>`}
function hallPage(){const ind=(DATA.hall_of_fame?.individual||[]).filter(x=>x.gw<=selectedGw),grp=(DATA.hall_of_fame?.groups||[]).filter(x=>x.gw<=selectedGw);return `${pageHeader('Hall of Fame','Weekly champions and group winners')}<section class="section"><div class="section-head"><h2>Weekly Champions</h2></div>${ind.length?ind.map(x=>`<div class="hof-item"><div class="gw">GW${x.gw}</div><div><strong>${x.winners.map(w=>`<a class="team-link" href="#/manager/${w.id}">${esc(w.team_name)}</a>`).join(', ')}</strong><small>${x.winners.map(w=>esc(w.chapter)).join(' • ')}</small></div><strong>${x.score}</strong></div>`).join(''):'<div class="empty">No finalized gameweek yet.</div>'}</section><section class="section"><div class="section-head"><h2>Group GW Champions</h2></div>${grp.length?grp.map(x=>`<div class="hof-item"><div class="gw">GW${x.gw}</div><div><strong>${x.winners.map(w=>`<a class="chapter-link" href="#/group/${enc(w)}">${esc(w)}</a>`).join(', ')}</strong></div><strong>${x.score}</strong></div>`).join(''):'<div class="empty">No finalized gameweek yet.</div>'}</section>`}
function morePage(){return `${pageHeader('More','Season tools and records')}<div class="more-grid"><a class="more-card" href="#/statistics"><span>↗</span>Statistics</a><a class="more-card" href="#/hall"><span>★</span>Hall of Fame</a><a class="more-card" href="#/chapters"><span>⌗</span>All Chapters</a><a class="more-card" href="#/individual"><span>≡</span>Full Ranking</a></div><div class="notice">Public dashboard contains ranking data only. Admin verification, participant master, Entry IDs and calculation engine are not published here.</div>`}
function notFound(){return `${pageHeader('Not Found','The requested ranking page does not exist.')}<div class="empty"><a class="team-link" href="#/home">Back to ANSARA FPL</a></div>`}
function getRoute(){return (location.hash.replace(/^#\/?/,'')||'home').split('/').filter(Boolean)}
function render(){if(!DATA)return;updateChrome();const [route,arg]=getRoute();let html='';switch(route){case'home':html=homePage();break;case'individual':html=individualPage();break;case'groups':html=groupsPage();break;case'chapters':html=chaptersPage();break;case'manager':html=managerPage(arg);break;case'chapter':html=chapterPage(dec(arg||''));break;case'group':html=groupPage(dec(arg||''));break;case'statistics':html=statisticsPage();break;case'hall':html=hallPage();break;case'more':html=morePage();break;default:html=notFound()}$('#app').innerHTML=html;wirePage();window.scrollTo({top:0,behavior:'instant'})}
function wirePage(){
  $$('[data-mode]').forEach(b=>b.onclick=()=>{rankMode=b.dataset.mode;render()});
  const cf=$('#chapterFilter');if(cf)cf.onchange=e=>{chapterFilter=e.target.value;render()};
  const sh=$('#shareProfile');if(sh)sh.onclick=shareCurrent;
}
async function shareCurrent(){const title='ANSARA FPL',url=location.href;try{if(navigator.share)await navigator.share({title,url});else{await navigator.clipboard.writeText(url);toast('Link copied')}}catch{}}
function setupSearch(){const d=$('#searchDialog'),input=$('#searchInput'),results=$('#searchResults');$('#searchTrigger').onclick=()=>{d.showModal();input.value='';renderSearch('');setTimeout(()=>input.focus(),50)};input.oninput=()=>renderSearch(input.value);function renderSearch(q){q=q.trim().toLowerCase();const managers=DATA.individual.filter(x=>!q||[x.full_name,x.manager_name,x.team_name,x.chapter].some(v=>String(v).toLowerCase().includes(q))).slice(0,20);const chapters=DATA.chapters.filter(c=>q&&c.chapter.toLowerCase().includes(q)).slice(0,8);results.innerHTML=`${managers.map(x=>`<a class="search-item" href="#/manager/${x.id}" onclick="document.getElementById('searchDialog').close()"><div><strong>${esc(x.team_name)}</strong><small>${esc(x.manager_name)} • ${esc(x.chapter)}</small></div><span>#${historicalRanking().find(r=>r.id===x.id)?.rank||'—'}</span></a>`).join('')}${chapters.map(c=>`<a class="search-item" href="#/chapter/${enc(c.chapter)}" onclick="document.getElementById('searchDialog').close()"><div><strong>${esc(c.chapter)}</strong><small>${c.managers} managers</small></div><span>Chapter</span></a>`).join('')}${!managers.length&&!chapters.length?'<div class="empty">No results.</div>':''}`}}
async function load(force=false){
  $('#app').innerHTML='<div class="loading"><div class="spinner"></div><p>Loading ANSARA FPL…</p></div>';
  try{const bust=Date.now();MANIFEST=await fetch(`data/manifest.json?v=${bust}`,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Manifest unavailable');return r.json()});DATA=await fetch(`${MANIFEST.snapshot}?v=${encodeURIComponent(MANIFEST.build_id)}`,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Ranking snapshot unavailable');return r.json()});rankCache.clear();groupCache.clear();selectedGw=Math.min(selectedGw||DATA.meta.gw,DATA.meta.gw);if(!force)selectedGw=DATA.meta.gw;const sel=$('#gwSelect');sel.innerHTML=Array.from({length:DATA.meta.gw},(_,i)=>i+1).reverse().map(g=>`<option value="${g}">GW${g}</option>`).join('');sel.value=String(selectedGw);sel.onchange=e=>{selectedGw=Number(e.target.value);render()};setupSearch();render()}catch(e){console.error(e);$('#app').innerHTML=`<div class="notice"><strong>Could not load ranking data.</strong><br>${esc(e.message)}</div>`}}
$('#refreshBtn').onclick=()=>load(true);window.addEventListener('hashchange',render);if(!location.hash)location.hash='#/home';load(false);
})();
